// Parsers for the DigitalOcean billing responses the FinOps page uses (and the size price list).
// Pure: no network, so they can be tested directly. Anything missing or malformed becomes a safe default.

export interface Balance {
  /** What has been used in the current billing period, in USD. */
  monthToDateUsage: number;
  accountBalance: number;
  generatedAt?: string;
}

export interface InvoiceRef {
  uuid: string;
  /** "2026-09" */
  period: string;
  amount: number;
  updatedAt?: string;
}

export interface InvoiceList {
  /** The current month, regenerated by DigitalOcean about once a day. */
  preview?: InvoiceRef & { accountUrn?: string };
  /** Past invoices, newest first. */
  invoices: InvoiceRef[];
}

export interface InvoiceItem {
  product: string;
  description: string;
  /** For Kubernetes lines, the cluster name. */
  groupDescription?: string;
  projectName?: string;
  resourceUuid?: string;
  amount: number;
  /** As DigitalOcean reports it. Not always hours even when the unit says so (backups count days). */
  duration: number;
  durationUnit: string;
  start?: string;
  end?: string;
}

export interface InsightPoint {
  /** "2026-10-01" (UTC day). */
  date: string;
  amount: number;
  description: string;
  sku: string;
  groupDescription?: string;
}

export interface SizePrice {
  slug: string;
  priceHourly: number;
  priceMonthly: number;
  vcpus: number;
  memoryMb: number;
}

type Obj = Record<string, unknown>;

const obj = (value: unknown): Obj => (value && typeof value === "object" && !Array.isArray(value) ? (value as Obj) : {});
const arr = (value: unknown): unknown[] => (Array.isArray(value) ? value : []);
const str = (value: unknown): string => (typeof value === "string" ? value : "");
const opt = (value: unknown): string | undefined => (typeof value === "string" && value !== "" ? value : undefined);

/** DigitalOcean sends money as strings ("41.14") and some counts as strings ("166"). */
export function money(value: unknown): number {
  const n = typeof value === "number" ? value : typeof value === "string" && value.trim() !== "" ? Number(value) : NaN;
  return Number.isFinite(n) ? n : 0;
}

export function parseBalance(body: unknown): Balance | null {
  const b = obj(body);
  if (!("month_to_date_usage" in b)) return null;
  return { monthToDateUsage: money(b.month_to_date_usage), accountBalance: money(b.account_balance), generatedAt: opt(b.generated_at) };
}

function invoiceRef(raw: unknown): InvoiceRef | null {
  const i = obj(raw);
  const uuid = str(i.invoice_uuid);
  const period = str(i.invoice_period);
  if (!uuid || !/^\d{4}-\d{2}$/.test(period)) return null;
  return { uuid, period, amount: money(i.amount), updatedAt: opt(i.updated_at) };
}

export function parseInvoiceList(body: unknown): InvoiceList {
  const b = obj(body);
  const preview = invoiceRef(b.invoice_preview);
  return {
    preview: preview ? { ...preview, accountUrn: opt(obj(b.invoice_preview).account_urn) } : undefined,
    invoices: arr(b.invoices)
      .map(invoiceRef)
      .filter((i): i is InvoiceRef => i !== null)
      .sort((a, b) => b.period.localeCompare(a.period)),
  };
}

export function parseInvoiceItems(body: unknown): { items: InvoiceItem[]; total: number } {
  const b = obj(body);
  const items = arr(b.invoice_items).map((raw): InvoiceItem => {
    const i = obj(raw);
    return {
      product: str(i.product) || "Other",
      description: str(i.description),
      groupDescription: opt(i.group_description),
      projectName: opt(i.project_name),
      resourceUuid: opt(i.resource_uuid),
      amount: money(i.amount),
      duration: money(i.duration),
      durationUnit: str(i.duration_unit),
      start: opt(i.start_time),
      end: opt(i.end_time),
    };
  });
  return { items, total: money(obj(b.meta).total) || items.length };
}

export function parseInsights(body: unknown): { points: InsightPoint[]; totalPages: number } {
  const b = obj(body);
  const points = arr(b.data_points)
    .map((raw): InsightPoint => {
      const p = obj(raw);
      return { date: str(p.start_date), amount: money(p.total_amount), description: str(p.description), sku: str(p.sku), groupDescription: opt(p.group_description) };
    })
    .filter((p) => /^\d{4}-\d{2}-\d{2}$/.test(p.date));
  return { points, totalPages: Math.max(1, Math.floor(money(b.total_pages))) };
}

export function parseSizes(body: unknown): SizePrice[] {
  return arr(obj(body).sizes)
    .map((raw) => {
      const s = obj(raw);
      return { slug: str(s.slug), priceHourly: money(s.price_hourly), priceMonthly: money(s.price_monthly), vcpus: money(s.vcpus), memoryMb: money(s.memory) };
    })
    .filter((s) => s.slug !== "");
}

/** The cluster's name as DigitalOcean knows it (it labels the invoice's Kubernetes lines). */
export function parseClusterName(body: unknown): string | undefined {
  return opt(obj(obj(body).kubernetes_cluster).name);
}
